from decimal import Decimal

def old_monthly_total(rows):
    return sum(float(row["amount"]) for row in rows)

def monthly_total(rows):
    return sum((Decimal(row["amount"]) for row in rows), Decimal("0")).quantize(Decimal("0.01"))

def test_decimal_avoids_float_error():
    rows = [{"amount": "0.10"}, {"amount": "0.20"}]

    assert old_monthly_total(rows) != 0.30
    assert monthly_total(rows) == Decimal("0.30")
```

