Yes—save this as `scripts/validate_week1.py`. It checks the manifest hashes, all BANKING77 JSONL splits, and synthetic appointments without requiring any paid services.

```python
from __future__ import annotations

import hashlib
import json
import sys
from datetime import datetime
from pathlib import Path
from typing import Literal

from pydantic import BaseModel, ValidationError


ROOT = Path(__file__).resolve().parents[1]
IRS_DIR = ROOT / "data/raw/irs"
BANKING_DIR = ROOT / "data/raw/banking77"
APPOINTMENTS = ROOT / "data/synthetic/appointments.jsonl"
MANIFEST = ROOT / "data/manifest.json"

INTENTS = {
    "card_arrival",
    "card_delivery_estimate",
    "card_not_received",
    "cash_withdrawal",
    "declined_cash_withdrawal",
    "cash_deposit",
    "beneficiary_not_allowed",
    "card_payment_wrong_exchange_rate",
    "card_payment_not_recognised",
    "pending_card_payment",
}

ALLOWED_ACTIONS = {"lookup", "draft_reschedule", "draft_cancel"}


class Appointment(BaseModel):
    customer_id: str
    name: str
    appointment_date: datetime
    visit_type: str
    status: Literal["scheduled", "cancelled", "completed"]
    allowed_actions: list[str]
    notes: str = ""


def sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as f:
        for chunk in iter(lambda: f.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def fail(message: str) -> None:
    print(f"ERROR: {message}")


def main() -> int:
    errors = []

    # Validate IRS PDFs against data/manifest.json.
    try:
        manifest = json.loads(MANIFEST.read_text())
        files = manifest["files"]

        for filename, metadata in files.items():
            path = IRS_DIR / filename
            if not path.is_file():
                errors.append(f"missing PDF: {path}")
                continue

            actual = sha256(path)
            expected = metadata["sha256"]
            if actual != expected:
                errors.append(
                    f"hash mismatch for {filename}: "
                    f"expected {expected}, got {actual}"
                )
    except Exception as exc:
        errors.append(f"could not validate manifest: {exc}")

    # Validate selected BANKING77 labels.
    banking_files = sorted(BANKING_DIR.glob("*.jsonl"))
    if not banking_files:
        errors.append(f"no BANKING77 JSONL files found in {BANKING_DIR}")

    for path in banking_files:
        try:
            with path.open() as f:
                for line_number, line in enumerate(f, 1):
                    row = json.loads(line)
                    if not isinstance(row.get("text"), str) or not row["text"].strip():
                        errors.append(f"{path}:{line_number}: missing text")
                    if row.get("label") not in INTENTS:
                        errors.append(f"{path}:{line_number}: invalid label")
        except Exception as exc:
            errors.append(f"could not read {path}: {exc}")

    # Validate synthetic appointment records.
    seen_ids = set()
    try:
        with APPOINTMENTS.open() as f:
            for line_number, line in enumerate(f, 1):
                try:
                    record = Appointment.parse_raw(line)
                    if record.customer_id in seen_ids:
                        errors.append(f"{APPOINTMENTS}:{line_number}: duplicate customer_id")
                    seen_ids.add(record.customer_id)

                    unknown = set(record.allowed_actions) - ALLOWED_ACTIONS
                    if unknown:
                        errors.append(
                            f"{APPOINTMENTS}:{line_number}: unknown actions {unknown}"
                        )
                except (json.JSONDecodeError, ValidationError) as exc:
                    errors.append(f"{APPOINTMENTS}:{line_number}: invalid record: {exc}")
    except FileNotFoundError:
        errors.append(f"missing appointment fixture: {APPOINTMENTS}")

    if errors:
        for error in errors:
            fail(error)
        print(f"\nValidation failed with {len(errors)} error(s).")
        return 1

    print("Week 1 validation passed.")
    print(f"Validated {len(files)} IRS PDF(s), {len(banking_files)} BANKING77 file(s), "
          f"and {len(seen_ids)} appointment record(s).")
    return 0


if __name__ == "__main__":
    sys.exit(main())
```

