Use one sequential loop—never start the next request until the previous one has settled—and keep `activeAttempt` unchanged whenever the failure is a timeout or network error:

```js
const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));

async function submitWithRetry(data, maxAttempts = 4) {
  if (!activeAttempt) {
    activeAttempt = { key: crypto.randomUUID(), data: structuredClone(data) };
  }

  for (let attempt = 0; attempt < maxAttempts; attempt++) {
    const controller = new AbortController();
    let timedOut = false;
    const timer = setTimeout(() => {
      timedOut = true;
      controller.abort();
    }, 8000);

    try {
      const response = await fetch("/submissions", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Idempotency-Key": activeAttempt.key
        },
        body: JSON.stringify(activeAttempt.data),
        signal: controller.signal
      });

      const body = await response.json().catch(() => null);

      if (response.ok || response.status === 409 || response.status < 500) {
        activeAttempt = null; // definitive result
        return { response, body };
      }

      // Retry transient server errors (5xx) with the same key.
      if (attempt === maxAttempts - 1) {
        throw new Error(`Server returned ${response.status}`);
      }
    } catch (error) {
      const kind = timedOut ? "timeout" : "network";
      console.info(`Submission ${kind}; retaining the idempotency key.`);

      if (attempt === maxAttempts - 1) {
        throw error; // activeAttempt remains available for a later retry
      }
    } finally {
      clearTimeout(timer);
    }

    const backoff = 500 * 2 ** attempt + Math.random() * 250;
    await sleep(backoff);
  }
}
```

A `409` is handled as a completed application result, while timeout/network failures and retryable `5xx` responses reuse the same key; a fresh form attempt should explicitly set `activeAttempt = null` before calling this function.

