};

document.title = page.title;

const meta = [
  ["name", "description", page.description],
  ["property", "og:type", "article"],
  ["property", "og:title", page.title],
  ["property", "og:description", page.description],
  ["property", "og:url", page.url],
  ["property", "og:image", page.image],
  ["property", "og:image:alt", page.imageAlt],
  ["name", "twitter:card", "summary_large_image"],
  ["name", "twitter:title", page.title],
  ["name", "twitter:description", page.description],
  ["name", "twitter:image", page.image],
  ["name", "twitter:image:alt", page.imageAlt]
];

const head = document.head;
meta.forEach(([attribute, name, content]) => {
  const tag = document.createElement("meta");
  tag.setAttribute(attribute, name);
  tag.content = content;
  head.appendChild(tag);
});

const structuredData = {
  "@context": "https://schema.org",
  "@type": "Article",
  headline: page.title,
  description: page.description,
  url: page.url,
  image: page.image,
  author: { "@type": "Person", name: "Your Name" },
  datePublished: page.datePublished,
  dateModified: page.dateModified
};

const jsonLd = document.createElement("script");
jsonLd.type = "application/ld+json";
jsonLd.textContent = JSON.stringify(structuredData);
head.appendChild(jsonLd);
```

Keep `imageAlt` in the Open Graph tags because it improves the accessibility of shared previews; JSON-LD’s `image` field should remain the URL, not the alt text. In a server-rendered template, use the same object to print tags directly so crawlers receive the metadata without waiting for JavaScript.

