EXPECTED_HEADERS = ("category", "description", "amount")


class CSVSchemaError(ValueError):
    pass


def validate_headers(headers):
    if headers is None:
        raise CSVSchemaError("CSV is missing a header row")

    missing = [name for name in EXPECTED_HEADERS if name not in headers]
    extra = [name for name in headers if name not in EXPECTED_HEADERS]

    if missing or extra:
        parts = []
        if missing:
            parts.append(f"missing columns: {missing!r}")
        if extra:
            parts.append(f"unexpected columns: {extra!r}")
        raise CSVSchemaError("Invalid CSV headers: " + "; ".join(parts))


def read_transactions(text):
    reader = csv.DictReader(StringIO(text, newline=""))
    return reader.fieldnames, list(reader)


def group_by_category(headers, rows):
    validate_headers(headers)

    grouped = OrderedDict()
    for row in rows:
        grouped.setdefault(row["category"], []).append(row)
    return grouped
