from dataclasses import dataclass
from io import StringIO
import csv
import re

import pytest


def rows_to_csv(rows, fieldnames=("category", "description", "amount")):
    output = StringIO(newline="")
    writer = csv.DictWriter(output, fieldnames=fieldnames)
    writer.writeheader()
    writer.writerows(rows)
    return output.getvalue()


@dataclass(frozen=True)
class FailureSpec:
    check: object
    expected: object
    exception: type
    message: str


def grouped_failure(expected_grouped):
    return FailureSpec(
        check=assert_grouped_rows_match,
        expected=expected_grouped,
        exception=AssertionError,
        message="Row-order/content failure for category 'Food'",
    )


def category_order_failure(expected_grouped):
    return FailureSpec(
        check=assert_category_order_match,
        expected=list(expected_grouped),
        exception=AssertionError,
        message="Category insertion-order failure",
    )


def missing_category_failure(_expected_grouped):
    return FailureSpec(
        check=None,
        expected=None,
        exception=KeyError,
        message="'category'",
    )


@pytest.fixture
def malformed_csv(request, canonical_rows):
    rows = canonical_rows.copy()

    if request.param == "swapped-row":
        rows[0], rows[4] = rows[4], rows[0]
        return rows_to_csv(rows)

    if request.param == "wrong-category-order":
        rows[2], rows[3] = rows[3], rows[2]
        return rows_to_csv(rows)

    if request.param == "missing-category-column":
        return rows_to_csv(
            [
                {
                    "description": row["description"],
                    "amount": row["amount"],
                }
                for row in rows
            ],
            fieldnames=("description", "amount"),
        )

    raise ValueError(f"Unknown CSV case: {request.param}")


@pytest.mark.parametrize(
    ("malformed_csv", "failure_factory"),
    [
        pytest.param(
            "swapped-row",
            grouped_failure,
            id="swapped-row",
        ),
        pytest.param(
            "wrong-category-order",
            category_order_failure,
            id="wrong-category-order",
        ),
        pytest.param(
            "missing-category-column",
            missing_category_failure,
            id="missing-category-column",
        ),
    ],
    indirect=["malformed_csv"],
)
def test_csv_grouping_failures(
    malformed_csv,
    failure_factory,
    expected_grouped,
):
    failure = failure_factory(expected_grouped)

    with pytest.raises(failure.exception, match=re.escape(failure.message)):
        rows = read_transactions(malformed_csv)
        actual = group_by_category(rows)

        # The missing-column case fails in group_by_category; the other
        # cases reach their explicitly selected comparison helper.
        failure.check(actual, failure.expected)
```

Each parameter supplies the failure behavior directly, so no helper is selected by inspecting an error-message string; adding another case only requires a CSV transformation and a `FailureSpec` factory.

