Normalize the BOM on the first header before parsing rows, then detect duplicates explicitly in `validate_headers`:

```python
from collections import Counter
import csv
from io import StringIO


def read_transactions(text):
    # If callers provide bytes, decode with "utf-8-sig" before calling this.
    reader = csv.DictReader(StringIO(text, newline=""))
    headers = reader.fieldnames

    if headers:
        headers = [
            header.removeprefix("\ufeff") if index == 0 else header
            for index, header in enumerate(headers)
        ]
        # Ensure row dictionaries use the normalized header names.
        reader.fieldnames = headers

    return headers, list(reader)


def validate_headers(headers):
    if headers is None:
        raise CSVSchemaError("CSV is missing a header row")

    duplicates = [
        header
        for header, count in Counter(headers).items()
        if count > 1
    ]
    if duplicates:
        raise CSVSchemaError(
            f"Invalid CSV headers: duplicate columns: {duplicates!r}"
        )

    missing = [name for name in EXPECTED_HEADERS if name not in headers]
    extra = [name for name in headers if name not in EXPECTED_HEADERS]

    if missing or extra:
        parts = []
        if missing:
            parts.append(f"missing columns: {missing!r}")
        if extra:
            parts.append(f"unexpected columns: {extra!r}")
        raise CSVSchemaError("Invalid CSV headers: " + "; ".join(parts))
```

