def _csv_text(value):
    if isinstance(value, bytes):
        return value.decode("utf-8-sig")
    if isinstance(value, str):
        return value.removeprefix("\ufeff")
    raise TypeError("CSV input must be str or UTF-8 bytes")


def read_transactions(source):
    reader = csv.DictReader(StringIO(_csv_text(source), newline=""))
    return reader.fieldnames, list(reader)
